#include <stdio.h>
#include <string.h>

int main(void) {
    char line[1024];
    if (!fgets(line, sizeof(line), stdin)) line[0] = '\0';
    size_t len = strlen(line);
    if (len > 0 && line[len-1] == '\n') { line[--len] = '\0'; }
    if (len > 0 && line[len-1] == '\r') { line[--len] = '\0'; }

    int happy = 0, sad = 0;
    for (size_t i = 0; i + 2 < len; i++) {
        if (line[i] == ':' && line[i+1] == '-') {
            if (line[i+2] == ')') happy++;
            else if (line[i+2] == '(') sad++;
        }
    }

    if (happy > sad) printf("divertido\n");
    else if (sad > happy) printf("chateado\n");
    else printf("neutro\n");

    return 0;
}
